// === Tab: mySketch ===
let colors = [];
let maxCircles = 100;

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();

  // カラーパレットの生成
  colors = [
    color(255, 0, 100),  // ピンク
    color(0, 150, 255),  // ブルー
    color(0, 255, 150),  // グリーン
    color(255, 200, 0),  // イエロー
    color(150, 0, 255)   // パープル
  ];

  background(30);
}

function draw() {
  for (let i = 0; i < 10; i++) { // 1フレームで複数の円を描く
    let x = random(width);
    let y = random(height);
    let size = random(10, 100);
    let col = random(colors);

    fill(col);
    ellipse(x, y, size, size);
  }

  // 一定数を超えたらリセット
  if (frameCount > maxCircles) {
    background(30);
    frameCount = 0;
  }
}

